"""Edit FM gradients, field-aware factors and evaluation cases."""
from pathlib import Path
import sys
ROOT=Path(__file__).resolve().parents[2];sys.path.insert(0,str(ROOT/'tools'))
from edit_chapter import load,save,transform
paragraphs={
'Для FM interaction score и':r'''Для оценки взаимодействий FM и $s=\sum_jv_jx_j$ производная по вектору $v_i$ равна''',
'Выражение s содержит self contribution':r'''Из суммы s вычитается собственный вклад $v_ix_i$: пары признака с самим собой в оценке нет. На числах предыдущего раздела производные по v₁,v₂,v₃ равны (8,−2.5), (6,3), (−7,0). При проверке конечными разностями нужно менять одну координату и пересчитывать всю оценку, включая обе части тождества; иначе проверяется другая функция.''',
'Для binary cross-entropy с':r'''Для бинарной кросс-энтропии с логитом $\widehat y$ множитель ошибки равен $\delta=\sigma(\widehat y)-y$. При L2-штрафе $\lambda\sum_i\|v_i\|^2/2$ градиент равен''',
'Если objective (оптимизируемая':'''Если функция потерь усредняется по пакету, градиенты данных усредняют один раз, а масштаб регуляризации задают относительно этой функции. Для квадрата ошибки множитель другой; для ранжирования он зависит от пары и способа её выбора. Общий фактор обновляется по всем объектам и партнёрам, где участвует, поэтому улучшение одной пары может ухудшить другую.''',
'Для одной active pair':'''Пусть активна одна пара: x₁=x₂=1, d=1, v₁=1, v₂=2, y=1. Логит равен 2, p≈0.880797, δ≈−0.119203. Без регуляризации градиенты факторов равны 2δ и δ. При шаге 0.1 одновременное обновление даёт v₁≈1.0238406, v₂≈2.0119203. Оба градиента вычислены по исходным значениям; последовательное изменение одного фактора до расчёта второго — другой алгоритм.''',
'При всех factors, инициализированных':'''Если все факторы инициализированы нулём, s и градиент ветви взаимодействий тоже равны нулю. Обычный градиентный спуск с L2 не выйдет из этого состояния: основные эффекты могут обучаться, но сами по себе не создадут градиент факторов. Ненулевая инициализация или другой явный механизм нарушает симметрию.''',
'FFM даёт feature':'''Факторизационная машина с учётом поля (field-aware factorization machine, FFM) задаёт признаку отдельный вектор для поля партнёра:''',
'$f_i$ — field feature':r'''$f_i$ — поле признака $i$. У города A могут быть разные представления для взаимодействия с днём и с товаром. Это гибче FM, но полный набор векторов увеличивает число параметров примерно с $Kd$ до $KFd$ и требует больше данных. Точная стоимость зависит от исключённых пар и хранения.''',
'FFM не равен просто concatenation':'''FFM не сводится к объединению обычных векторов с линейной головой: правило взаимодействия задано отдельно. Нейросети тоже могут обучать взаимодействия, но их предположения, ёмкость и оптимизация отличаются. Автоматические сочетания CatBoost — другой механизм: комбинации превращаются в статистики или разбиения, а не обязательно в факторизованные произведения. См. [исходную работу о FFM](https://www.csie.ntu.edu.tw/~cjlin/papers/ffm.pdf).''',
'Пусть одновременно активны city A':r'''Пусть одновременно активны город A, день D и товар P. У A есть векторы $v_{A,day}$ и $v_{A,product}$; партнёры используют встречные векторы $v_{D,city}$ и $v_{P,city}$. Поле — тип признака, а не ID конкретной категории: все товары обращаются к представлению города для поля товара.''',
'Зададим $v_{A,day}':r'''Зададим $v_{A,day}=(1,0)$, $v_{D,city}=(3,1)$; $v_{A,product}=(0,2)$, $v_{P,city}=(2,-1)$; $v_{D,product}=(1,1)$, $v_{P,day}=(-1,4)$. Три вклада равны 3,−2,3, сумма — 4. Если заменить только $v_{A,product}$ на (0,3), вклад A–P станет −3, а A–D останется 3; сумма станет 3. В обычной FM у A один общий вектор, и его изменение обычно затрагивает всех партнёров.''',
'Для pair i,j data gradient':r'''Для пары i,j градиент данных по $v_{i,f_j}$ равен $\delta x_ix_jv_{j,f_i}$; встречный градиент симметричен. Если в поле несколько активных категорий, вклады соответствующих партнёров суммируются. Словари category ID и field ID должны быть стабильны отдельно: перестановка номеров полей без перестановки весов изменит модель при тех же ID категорий.''',
'General FFM теряет':r'''В общем случае для FFM не действует простое тождество квадрата FM: у признака нет одного общего вектора для всех пар. Прямой разреженный проход стоит $O(m^2d)$ по m активным признакам. При одном значении в каждом поле $m\approx F$; для длинных многозначных наборов m может быть гораздо больше F. Оптимизация реализации возможна, но линейную по m стоимость обычной FM нельзя обещать произвольной FFM.''',
'При K=1 000 000,F=20':'''При K=1 000 000, F=20, d=8 полный тензор K×F×d содержит 160 миллионов чисел, или 640 MB весов float32 в десятичных единицах. Если векторы для собственного поля не нужны, K(F−1)d занимают 608 MB. Градиенты и состояние оптимизатора могут увеличить память в несколько раз. Разреженное хранение сокращает незадействованные записи, только если реализация действительно их не выделяет.''',
'Rare interactions легко':'''Редкие взаимодействия легко запоминаются. Нужны разделение групп или времени, регуляризация и отдельный анализ новых сочетаний. Пара из двух известных категорий и пара с совершенно новой категорией — разные режимы; их полезно оценивать отдельно.''',
'Сначала additive baseline':'''Сначала проверьте аддитивную базовую модель, затем одно сочетание или FM/FFM с сопоставимым бюджетом подбора. Кроме общей метрики оцените память, качество редких пар и сохранённый словарь. Если улучшение исчезает при разделении групп, взаимодействие могло запомнить сочетания ID.''',
'Известные city A и product P':'''Известные город A и товар P могли встречаться только с другими партнёрами. FM может вычислить оценку новой пары из уже обученных векторов; качество зависит от пригодности низкорангового предположения и достаточности данных. Если A совершенно новый и его признаки отсутствуют, индивидуальный фактор неизвестен. Резервный UNK или группа дадут определённый ответ, но не выученный эффект A.''',
'Полезно заранее разделить режимы evaluation':'''Заранее разделите проверку на наблюдавшуюся пару, новую пару из известных категорий, пару с одним новым компонентом и пару с двумя новыми компонентами. Разбиение по группам или времени выбирают под задачу; словари и настройки определяют внутри разрешённой обучающей части. Глобальный список известных объектов по всем данным может скрыть, что объект ещё не существовал к моменту прогноза.''',
'В sparse feedback, например clicks':'''При разреженной обратной связи, например кликах, отсутствие взаимодействия не всегда означает отрицательную метку: объект могли не показать пользователю. Выбор отрицательных примеров, показы и политика журналирования меняют обучающее распределение. Поэтому произведение векторов, обученное на выбранных отрицательных примерах, не становится автоматически калиброванной вероятностью реального клика. Сначала определяют наблюдаемый исход и доступные показы, затем выборку, веса и оценку.''',
'Для serialization сохраняют':r'''При сохранении фиксируют пространства имён, нормализацию, словари категорий и полей, смысл активного значения (индикатор, количество или вес), разрешённые пары, факторы, основные эффекты, смещение, функцию связи и правила неизвестных значений. Проверка после загрузки должна включать взвешенный разреженный пример и многозначное поле, если они поддерживаются: ошибка $x_i^2$ в диагональной поправке не проявится на одних бинарных значениях.'''
}
def op(t):
 for prefix,new in paragraphs.items():
  a=t.find(prefix)
  if a<0:raise ValueError('Missing paragraph: '+prefix)
  ends=[i for i in (t.find('\n\n',a),t.find('\n<!-- EDIT:',a),t.find('\n<!-- /EDIT:',a)) if i>=0]
  if not ends:raise ValueError('Missing boundary: '+prefix)
  b=min(ends);t=t[:a]+new+t[b:]
 return t
c=load();transform('01-data-features/02-features/feat-interactions.md',op,
 'Пакет 03: редактура градиентов FM, FFM и оценки новых сочетаний с сохранением расчётов; приёмка ожидается.',c);save(c)
print('FM gradients, FFM and evaluation edited; review remains open.')
